#include <vector>
#include <omp.h>

bool reduceLogicalXOR(std::vector<bool> const& x) {
    int acc = 0; // use int for OpenMP reduction portability
    const int n = static_cast<int>(x.size());

#pragma omp parallel for reduction(^ : acc)
    for (int i = 0; i < n; ++i) {
        acc ^= static_cast<int>(x[static_cast<std::size_t>(i)]);
    }

    return acc != 0;
}
